'*{box-sizing:border-box;margin:0;padding:0}
body{overflow:hidden;background:transparent}
.strip{display:flex;gap:14px;height:100%;align-items:stretch;
  font-family:''Segoe UI Variable Display'',''Segoe UI'',system-ui,sans-serif}
.c{flex:1 1 0;min-width:0;position:relative;overflow:hidden;background:#FFFFFF;
  border:1px solid #E3E8EF;border-radius:14px;padding:11px 14px 13px;
  box-shadow:0 3px 14px rgba(15,23,42,.06);
  animation:rise .5s cubic-bezier(.22,.8,.28,1) backwards;
  animation-delay:calc(var(--i) * 55ms);
  transition:box-shadow .22s ease,transform .22s ease,border-color .22s ease}
.c:hover{box-shadow:0 8px 24px rgba(15,23,42,.11);transform:translateY(-2px);border-color:#CFD8E3}
.k{font-size:10px;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:#5B6672;white-space:nowrap}
.m{height:36px;margin-top:3px}
.v{font-size:27px;line-height:36px;font-weight:600;letter-spacing:-.02em;color:#111827;white-space:nowrap}
.v small{font-size:13px;font-weight:500;color:#5B6672;letter-spacing:0}
.p{font-size:12px;color:#5B6672;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.r{position:absolute;left:0;bottom:0;height:3px;width:100%;background:var(--a);border-radius:0 3px 0 0;
  animation:grow .75s cubic-bezier(.22,.8,.28,1) backwards;
  animation-delay:calc(var(--i) * 55ms + 120ms)}
.r::after{content:'''';position:absolute;inset:0;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.75),transparent);
  animation:sheen 3.4s ease-in-out infinite;animation-delay:calc(var(--i) * 55ms + 1000ms)}
/* Entrance animates transform and the accent width only - never opacity, and
   never a mask over the value. Power BI restarts CSS animations every time the
   page is shown, and animation-delay with fill-mode:backwards holds the FROM
   state for the length of the delay, so anything faded or masked here would
   leave the headline numbers invisible for ~400ms on every single visit. A
   half-played translate still shows a fully readable card. */
@keyframes rise{from{transform:translateY(9px)}}
@keyframes grow{from{width:0}}
@keyframes sheen{0%{transform:translateX(-100%)}60%,100%{transform:translateX(100%)}}
@media (prefers-reduced-motion:reduce){
  .c,.r{animation:none!important}
  .r::after{display:none}
}'
